CREATE   VIEW [Subs].[vwSubsOmni] AS

	SELECT 
	 Contact_No AS 'Contact No.'
	,Contact_ID AS 'Contact ID'
	,Campaign_Year AS 'Campaign Year'
	,Quote_ID AS 'Quote ID'
	,Quote_Number AS 'Quote No.'
	,Created_Date AS 'Created Date'
	,Quote_Amount_CUR AS 'Quote Amount CUR'
	,Quote_Amount_GBP AS 'Quote Amount GBP'
	,Quote_Currency AS 'Quote Currency'
	,Quote_Payment_Method AS 'Quote Payment Method'
	,Quote_State AS 'Quote State'
	,Quote_Status AS 'Quote Status'
	,[Sales_Order_ID] AS 'Sales Order ID'
	,[Sales_Order_No] AS 'Sales Order No'
	,Invoice AS 'Invoice'
	,Voucher AS 'Voucher'
	,Trans_Date AS 'Trans Date'
	,Inv_Currency AS 'Inv Currency'
	,Invoice_Amount_CUR AS 'Invoice Amount CUR'
	,Invoice_Amount_GBP AS 'Invoice Amount GBP'
	,Settle_Amount_CUR AS 'Settle Amount CUR'
	,Settle_Amount_GBP AS 'Settle Amount GBP'
	,Paid_Amount_CUR AS 'Paid Amount CUR'
	,Paid_Amount_GBP AS 'Paid Amount GBP'
	,Balance_CUR AS 'Balance CUR'
	,Balance_GBP AS 'Balance GBP'
	,Payment_Status AS 'Payment Status'
	FROM [Subs].[tblSubsOmni]
